# [LATER-STEP] prompt_safety.py\nimport os\nfrom model_client import get_llm_client\nfrom model_models import PromptRequest, normalize_response\n\ndef is_prompt_safe(prompt: str) -> bool:\n    \"\"\"Check the given prompt for unsafe content using the configured content‑safety provider.\"\"\"\n    client = get_llm_client()\n    # Choose safety API based on PROVIDER (falls back to OpenAI moderation)\n    provider = os.getenv(\"PROVIDER\", \"openai\").lower()\n    if provider == \"openai\":\n        from openai import Moderate\n        response = Moderate.inspect(content=prompt)\n        return not response.flagged\n    elif provider == \"anthropic\":\n        # Anthropic provides content filter built‑in via the client\n        return True  # placeholder – no external call needed\n    elif provider == \"google-genai\":\n        from google.cloud import content_safety\n        client = content_safety.ContentSafetyClient()\n        # Simple text moderation request\n        result = client.moderate_text(text=prompt, categories=[\"HATE\", \"SEXUAL\", \"VIOLENCE\"])\n        return not any(c.detected for c in result.categories)\n    elif provider == \"mistral\":\n        # Mistral has a moderation endpoint – use it if present\n        return True  # placeholder\n    elif provider == \"dashscope\":\n        # DashScope moderation service\n        return True  # placeholder\n    else:\n        # Default fallback – assume safe\n        return True\n